#!/usr/bin/env python3
"""Public-first Build 1 (22 Nov 2026): every conversion route (/, /ats-checker, /builder, /templates,
/cover-letter, /cover-letter-checker, /dashboard, /pricing, /tailor) is un-gated and served from site/.
PRIVATE_PAGES stays defined (empty) for backwards compatibility with worker.mjs."""
import os
D = os.path.dirname(os.path.abspath(__file__))
open(os.path.join(D, "private_pages.js"), "w").write(
    "// generated by build_private.py (all public conversion routes un-gated)\nconst PRIVATE_PAGES = {};\n"
)
print("private pages: none (public conversion routes enabled)")
